-- Banco inicial de preguntas por eje (CU08) — Matemática 4° básico.
-- BORRADOR del equipo de desarrollo: todas quedan con revisada_pedagogicamente = FALSE
-- hasta que el equipo pedagógico de Triskel Edu las valide.
-- Cada distractor indica el error típico que lo explica (tabla tipo_error).
-- Es idempotente: si la pregunta ya existe (mismo código) actualiza su contenido, salvo que
-- ya esté revisada pedagógicamente (desde ese momento manda lo que edite el administrador).
-- Nunca toca `activa` ni `revisada_pedagogicamente`.
INSERT INTO pregunta (codigo, eje_id, enunciado, opciones, respuesta_correcta, dificultad, estrategia, explicacion)
SELECT v.codigo, e.id, v.enunciado, v.opciones::jsonb, v.correcta, v.dificultad, v.estrategia, v.explicacion
FROM (VALUES
  -- ───────── Números y operaciones ─────────
  ('NUM-01', 'numeros', '¿Cómo se escribe con cifras «dos mil cincuenta»?',
   '[{"clave":"A","texto":"2.050","tipo_error":null},{"clave":"B","texto":"2.500","tipo_error":"valor_posicional"},{"clave":"C","texto":"20.050","tipo_error":"valor_posicional"},{"clave":"D","texto":"2.005","tipo_error":"valor_posicional"}]',
   'A', 1, 'numerica', 'Dos mil son 2 unidades de mil y cincuenta son 5 decenas: 2.050. Las centenas quedan en 0.'),
  ('NUM-02', 'numeros', '¿Cuál es el valor del dígito 4 en el número 3.482?',
   '[{"clave":"A","texto":"4","tipo_error":"valor_posicional"},{"clave":"B","texto":"40","tipo_error":"valor_posicional"},{"clave":"C","texto":"400","tipo_error":null},{"clave":"D","texto":"4.000","tipo_error":"valor_posicional"}]',
   'C', 1, 'numerica', 'El 4 está en la posición de las centenas, así que vale 4 centenas: 400.'),
  ('NUM-03', 'numeros', 'Sofía tiene 245 láminas y le regalan 138. ¿Cuántas láminas tiene ahora?',
   '[{"clave":"A","texto":"383","tipo_error":null},{"clave":"B","texto":"373","tipo_error":"reserva_suma"},{"clave":"C","texto":"107","tipo_error":"operacion_equivocada"},{"clave":"D","texto":"283","tipo_error":"calculo"}]',
   'A', 1, 'concreta', 'Le regalan láminas, entonces sumamos: 245 + 138. Las unidades dan 5 + 8 = 13: anotamos 3 y llevamos 1 a las decenas. Resultado: 383.'),
  ('NUM-04', 'numeros', 'En una caja caben 6 huevos. ¿Cuántos huevos hay en 7 cajas llenas?',
   '[{"clave":"A","texto":"13","tipo_error":"operacion_equivocada"},{"clave":"B","texto":"36","tipo_error":"tabla_multiplicar"},{"clave":"C","texto":"42","tipo_error":null},{"clave":"D","texto":"48","tipo_error":"tabla_multiplicar"}]',
   'C', 2, 'concreta', 'Son 7 grupos de 6 huevos: 7 × 6 = 42. Puedes pensarlo como 6 + 6 + 6 + 6 + 6 + 6 + 6.'),
  ('NUM-05', 'numeros', '¿Cuánto es 502 − 167?',
   '[{"clave":"A","texto":"465","tipo_error":"resta_invertida"},{"clave":"B","texto":"335","tipo_error":null},{"clave":"C","texto":"345","tipo_error":"calculo"},{"clave":"D","texto":"669","tipo_error":"operacion_equivocada"}]',
   'B', 2, 'numerica', 'Como a 2 no se le puede restar 7, canjeamos: 502 es lo mismo que 4 centenas, 9 decenas y 12 unidades. 12 − 7 = 5, 9 − 6 = 3 y 4 − 1 = 3: el resultado es 335.'),
  ('NUM-06', 'numeros', 'Una pizza se cortó en 8 trozos iguales y Tomás comió 3. ¿Qué fracción de la pizza comió Tomás?',
   '[{"clave":"A","texto":"3/8","tipo_error":null},{"clave":"B","texto":"8/3","tipo_error":"fraccion_partes"},{"clave":"C","texto":"3/5","tipo_error":"fraccion_partes"},{"clave":"D","texto":"5/8","tipo_error":"fraccion_partes"}]',
   'A', 2, 'visual', 'El número de abajo (denominador) dice en cuántas partes iguales se cortó: 8. El de arriba (numerador) dice cuántas comió: 3. Tomás comió 3/8.'),
  ('NUM-07', 'numeros', 'Se reparten 56 lápices en partes iguales entre 8 estudiantes. ¿Cuántos lápices recibe cada uno?',
   '[{"clave":"A","texto":"6","tipo_error":"tabla_multiplicar"},{"clave":"B","texto":"7","tipo_error":null},{"clave":"C","texto":"48","tipo_error":"operacion_equivocada"},{"clave":"D","texto":"64","tipo_error":"operacion_equivocada"}]',
   'B', 3, 'concreta', 'Repartir en partes iguales es dividir: 56 : 8. Buscamos qué número por 8 da 56. Como 8 × 7 = 56, cada uno recibe 7 lápices.'),
  ('NUM-08', 'numeros', '¿Cuál de estos números es el mayor?',
   '[{"clave":"A","texto":"4.099","tipo_error":"valor_posicional"},{"clave":"B","texto":"4.901","tipo_error":null},{"clave":"C","texto":"4.190","tipo_error":"valor_posicional"},{"clave":"D","texto":"4.019","tipo_error":"valor_posicional"}]',
   'B', 3, 'verbal', 'Todos tienen 4 unidades de mil, así que comparamos las centenas: 4.901 tiene 9 centenas y los demás tienen 0 o 1. El mayor es 4.901.'),

  -- ───────── Patrones y álgebra ─────────
  ('PAT-01', 'patrones', '¿Qué número sigue en el patrón? 5, 10, 15, 20, …',
   '[{"clave":"A","texto":"21","tipo_error":"patron_regla"},{"clave":"B","texto":"25","tipo_error":null},{"clave":"C","texto":"30","tipo_error":"patron_regla"},{"clave":"D","texto":"40","tipo_error":"patron_regla"}]',
   'B', 1, 'visual', 'Cada número es 5 más que el anterior: 5, 10, 15, 20… El que sigue es 20 + 5 = 25.'),
  ('PAT-02', 'patrones', 'Si 12 + □ = 20, ¿qué número va en el cuadrado?',
   '[{"clave":"A","texto":"7","tipo_error":"calculo"},{"clave":"B","texto":"8","tipo_error":null},{"clave":"C","texto":"12","tipo_error":"ecuacion_inversa"},{"clave":"D","texto":"32","tipo_error":"ecuacion_inversa"}]',
   'B', 1, 'concreta', 'Buscamos cuánto le falta a 12 para llegar a 20. Usamos la resta: 20 − 12 = 8. Comprobamos: 12 + 8 = 20.'),
  ('PAT-03', 'patrones', '¿Qué número sigue en el patrón? 3, 7, 11, 15, …',
   '[{"clave":"A","texto":"17","tipo_error":"patron_regla"},{"clave":"B","texto":"19","tipo_error":null},{"clave":"C","texto":"20","tipo_error":"calculo"},{"clave":"D","texto":"30","tipo_error":"patron_regla"}]',
   'B', 2, 'numerica', 'La regla es sumar 4: 3 + 4 = 7, 7 + 4 = 11, 11 + 4 = 15. El que sigue es 15 + 4 = 19.'),
  ('PAT-04', 'patrones', '¿Qué número sigue en el patrón? 80, 72, 64, 56, …',
   '[{"clave":"A","texto":"40","tipo_error":"patron_regla"},{"clave":"B","texto":"48","tipo_error":null},{"clave":"C","texto":"50","tipo_error":"patron_regla"},{"clave":"D","texto":"64","tipo_error":"patron_regla"}]',
   'B', 2, 'numerica', 'Cada número es 8 menos que el anterior. El que sigue es 56 − 8 = 48.'),
  ('PAT-05', 'patrones', 'Si □ − 15 = 30, ¿qué número va en el cuadrado?',
   '[{"clave":"A","texto":"15","tipo_error":"ecuacion_inversa"},{"clave":"B","texto":"25","tipo_error":"calculo"},{"clave":"C","texto":"45","tipo_error":null},{"clave":"D","texto":"2","tipo_error":"operacion_equivocada"}]',
   'C', 2, 'concreta', 'A un número le quitamos 15 y quedaron 30. Para saber cuánto había, devolvemos los 15: 30 + 15 = 45. Comprobamos: 45 − 15 = 30.'),
  ('PAT-06', 'patrones', 'Un patrón empieza en 2 y cada número es el doble del anterior: 2, 4, 8, 16, … ¿Cuál es el sexto número?',
   '[{"clave":"A","texto":"18","tipo_error":"patron_regla"},{"clave":"B","texto":"24","tipo_error":"patron_regla"},{"clave":"C","texto":"32","tipo_error":"patron_regla"},{"clave":"D","texto":"64","tipo_error":null}]',
   'D', 3, 'verbal', 'Seguimos doblando: el quinto es 16 × 2 = 32 y el sexto es 32 × 2 = 64. ¡Ojo! 32 es el quinto, no el sexto.'),
  ('PAT-07', 'patrones', 'Una balanza está en equilibrio: a un lado hay 3 cajas iguales y al otro, 18 kg. ¿Cuánto pesa cada caja?',
   '[{"clave":"A","texto":"6 kg","tipo_error":null},{"clave":"B","texto":"15 kg","tipo_error":"ecuacion_inversa"},{"clave":"C","texto":"21 kg","tipo_error":"ecuacion_inversa"},{"clave":"D","texto":"54 kg","tipo_error":"ecuacion_inversa"}]',
   'A', 3, 'concreta', 'Las 3 cajas juntas pesan 18 kg. Repartimos 18 en 3 partes iguales: 18 : 3 = 6. Cada caja pesa 6 kg.'),

  -- ───────── Geometría ─────────
  ('GEO-01', 'geometria', '¿Qué figura tiene exactamente 3 lados?',
   '[{"clave":"A","texto":"Cuadrado","tipo_error":"figura_propiedades"},{"clave":"B","texto":"Triángulo","tipo_error":null},{"clave":"C","texto":"Pentágono","tipo_error":"figura_propiedades"},{"clave":"D","texto":"Círculo","tipo_error":"figura_propiedades"}]',
   'B', 1, 'visual', '«Tri» significa tres: el triángulo tiene 3 lados y 3 vértices. El cuadrado tiene 4 lados y el pentágono, 5.'),
  ('GEO-02', 'geometria', '¿Cuántas caras tiene un cubo?',
   '[{"clave":"A","texto":"4","tipo_error":"cuerpo_elementos"},{"clave":"B","texto":"6","tipo_error":null},{"clave":"C","texto":"8","tipo_error":"cuerpo_elementos"},{"clave":"D","texto":"12","tipo_error":"cuerpo_elementos"}]',
   'B', 1, 'visual', 'Piensa en un dado: tiene caras con 1, 2, 3, 4, 5 y 6 puntos. El cubo tiene 6 caras. 8 son sus vértices y 12 sus aristas.'),
  ('GEO-03', 'geometria', '¿Qué tipo de ángulo forman las manecillas del reloj a las 3 en punto?',
   '[{"clave":"A","texto":"Agudo","tipo_error":"angulo_tipo"},{"clave":"B","texto":"Recto","tipo_error":null},{"clave":"C","texto":"Obtuso","tipo_error":"angulo_tipo"},{"clave":"D","texto":"Extendido","tipo_error":"angulo_tipo"}]',
   'B', 2, 'visual', 'A las 3 en punto una manecilla apunta al 12 y la otra al 3: forman una esquina como la de una hoja de cuaderno. Ese es un ángulo recto (90°).'),
  ('GEO-04', 'geometria', '¿Cuántos vértices tiene una pirámide de base cuadrada?',
   '[{"clave":"A","texto":"4","tipo_error":"cuerpo_elementos"},{"clave":"B","texto":"5","tipo_error":null},{"clave":"C","texto":"6","tipo_error":"cuerpo_elementos"},{"clave":"D","texto":"8","tipo_error":"cuerpo_elementos"}]',
   'B', 2, 'visual', 'La base cuadrada tiene 4 vértices y arriba está la punta de la pirámide: 4 + 1 = 5 vértices. 8 es el número de aristas.'),
  ('GEO-05', 'geometria', 'Estás mirando hacia el norte y das un cuarto de vuelta hacia la derecha. ¿Hacia dónde quedas mirando?',
   '[{"clave":"A","texto":"Este","tipo_error":null},{"clave":"B","texto":"Oeste","tipo_error":"orientacion"},{"clave":"C","texto":"Sur","tipo_error":"orientacion"},{"clave":"D","texto":"Norte","tipo_error":"orientacion"}]',
   'A', 2, 'concreta', 'Si miras al norte, a tu derecha está el este. Un cuarto de vuelta a la derecha te deja mirando al este. Media vuelta te dejaría mirando al sur.'),
  ('GEO-06', 'geometria', '¿Cuál de estas letras tiene un eje de simetría vertical?',
   '[{"clave":"A","texto":"A","tipo_error":null},{"clave":"B","texto":"F","tipo_error":"simetria"},{"clave":"C","texto":"G","tipo_error":"simetria"},{"clave":"D","texto":"R","tipo_error":"simetria"}]',
   'A', 3, 'visual', 'Si doblas la letra A por una línea vertical en su centro, las dos mitades calzan exactamente. Con F, G y R las mitades no son iguales.'),
  ('GEO-07', 'geometria', '¿Qué tienen siempre en común un rectángulo y un cuadrado?',
   '[{"clave":"A","texto":"Tienen 4 ángulos rectos","tipo_error":null},{"clave":"B","texto":"Tienen sus 4 lados iguales","tipo_error":"figura_propiedades"},{"clave":"C","texto":"Tienen 3 vértices","tipo_error":"figura_propiedades"},{"clave":"D","texto":"Tienen lados curvos","tipo_error":"figura_propiedades"}]',
   'A', 3, 'verbal', 'Los dos tienen 4 lados y 4 ángulos rectos. Pero solo el cuadrado tiene siempre sus 4 lados iguales: un rectángulo puede ser más largo que ancho.'),

  -- ───────── Medición ─────────
  ('MED-01', 'medicion', '¿Cuántos centímetros hay en 1 metro?',
   '[{"clave":"A","texto":"10","tipo_error":"unidad_conversion"},{"clave":"B","texto":"60","tipo_error":"unidad_conversion"},{"clave":"C","texto":"100","tipo_error":null},{"clave":"D","texto":"1.000","tipo_error":"unidad_conversion"}]',
   'C', 1, 'concreta', 'Un metro tiene 100 centímetros. Una regla escolar de 30 cm cabe un poco más de 3 veces en un metro.'),
  ('MED-02', 'medicion', 'En un reloj, la manecilla corta apunta al 4 y la larga al 12. ¿Qué hora es?',
   '[{"clave":"A","texto":"4:00","tipo_error":null},{"clave":"B","texto":"12:04","tipo_error":"lectura_hora"},{"clave":"C","texto":"12:20","tipo_error":"lectura_hora"},{"clave":"D","texto":"4:12","tipo_error":"lectura_hora"}]',
   'A', 1, 'visual', 'La manecilla corta marca la hora (4) y la larga los minutos. Cuando la larga está en el 12 es «en punto»: son las 4:00.'),
  ('MED-03', 'medicion', '¿Cuál es el perímetro de un rectángulo de 5 cm de largo y 3 cm de ancho?',
   '[{"clave":"A","texto":"8 cm","tipo_error":"perimetro_area"},{"clave":"B","texto":"13 cm","tipo_error":"perimetro_area"},{"clave":"C","texto":"15 cm","tipo_error":"perimetro_area"},{"clave":"D","texto":"16 cm","tipo_error":null}]',
   'D', 2, 'numerica', 'El perímetro es lo que mide el borde completo: se suman los 4 lados. 5 + 3 + 5 + 3 = 16 cm. (15 sería el área, que se mide en cm²).'),
  ('MED-04', 'medicion', 'Si hoy es lunes 14, ¿qué fecha será el lunes siguiente?',
   '[{"clave":"A","texto":"15","tipo_error":"calendario"},{"clave":"B","texto":"20","tipo_error":"calendario"},{"clave":"C","texto":"21","tipo_error":null},{"clave":"D","texto":"28","tipo_error":"calendario"}]',
   'C', 2, 'concreta', 'Una semana tiene 7 días. El lunes siguiente es 7 días después: 14 + 7 = 21.'),
  ('MED-05', 'medicion', 'Una película empieza a las 15:30 y dura 1 hora y 45 minutos. ¿A qué hora termina?',
   '[{"clave":"A","texto":"16:15","tipo_error":"calculo"},{"clave":"B","texto":"16:75","tipo_error":"lectura_hora"},{"clave":"C","texto":"17:15","tipo_error":null},{"clave":"D","texto":"17:45","tipo_error":"calculo"}]',
   'C', 2, 'numerica', 'Primero sumamos la hora: 15:30 + 1 hora = 16:30. Luego 45 minutos: 30 minutos más llegan a las 17:00 y faltan 15 minutos: 17:15. Una hora tiene 60 minutos, por eso no existe 16:75.'),
  ('MED-06', 'medicion', 'Un cuadrado tiene un perímetro de 20 cm. ¿Cuánto mide cada lado?',
   '[{"clave":"A","texto":"4 cm","tipo_error":"calculo"},{"clave":"B","texto":"5 cm","tipo_error":null},{"clave":"C","texto":"10 cm","tipo_error":"perimetro_area"},{"clave":"D","texto":"80 cm","tipo_error":"operacion_equivocada"}]',
   'B', 3, 'visual', 'El cuadrado tiene 4 lados iguales que juntos miden 20 cm. Repartimos: 20 : 4 = 5. Cada lado mide 5 cm.'),
  ('MED-07', 'medicion', 'Una botella tiene 2 litros de jugo. ¿Cuántos vasos de 250 mililitros se pueden llenar?',
   '[{"clave":"A","texto":"4","tipo_error":"unidad_conversion"},{"clave":"B","texto":"6","tipo_error":"calculo"},{"clave":"C","texto":"8","tipo_error":null},{"clave":"D","texto":"10","tipo_error":"calculo"}]',
   'C', 3, 'concreta', '1 litro son 1.000 mililitros, así que 2 litros son 2.000 mL. Con 1 litro se llenan 4 vasos de 250 mL; con 2 litros, 8 vasos.'),

  -- ───────── Datos y probabilidades ─────────
  ('DAT-01', 'datos', 'En un curso votaron por su fruta favorita: manzana 8, plátano 5, uva 11 y pera 3. ¿Qué fruta tuvo más votos?',
   '[{"clave":"A","texto":"Manzana","tipo_error":"lectura_grafico"},{"clave":"B","texto":"Plátano","tipo_error":"lectura_grafico"},{"clave":"C","texto":"Uva","tipo_error":null},{"clave":"D","texto":"Pera","tipo_error":"lectura_grafico"}]',
   'C', 1, 'visual', 'Comparamos los votos: 11 es el número más grande, y corresponde a la uva.'),
  ('DAT-02', 'datos', 'En una bolsa hay solo bolitas rojas. Si sacas una sin mirar, sacar una bolita roja es…',
   '[{"clave":"A","texto":"Seguro","tipo_error":null},{"clave":"B","texto":"Posible, pero no seguro","tipo_error":"probabilidad_terminos"},{"clave":"C","texto":"Imposible","tipo_error":"probabilidad_terminos"},{"clave":"D","texto":"Poco probable","tipo_error":"probabilidad_terminos"}]',
   'A', 1, 'verbal', 'Si todas las bolitas son rojas, cualquiera que saques será roja. Es un suceso seguro.'),
  ('DAT-03', 'datos', 'En el curso votaron: manzana 8, plátano 5, uva 11 y pera 3. ¿Cuántos estudiantes votaron en total?',
   '[{"clave":"A","texto":"4","tipo_error":"conteo_tabla"},{"clave":"B","texto":"11","tipo_error":"lectura_grafico"},{"clave":"C","texto":"26","tipo_error":"calculo"},{"clave":"D","texto":"27","tipo_error":null}]',
   'D', 2, 'numerica', 'Para el total sumamos todos los votos: 8 + 5 + 11 + 3 = 27. (4 es la cantidad de frutas, no de votos).'),
  ('DAT-04', 'datos', 'En un gráfico de barras cada cuadrito representa 2 estudiantes. La barra de fútbol tiene 6 cuadritos. ¿Cuántos estudiantes eligieron fútbol?',
   '[{"clave":"A","texto":"3","tipo_error":"operacion_equivocada"},{"clave":"B","texto":"6","tipo_error":"lectura_grafico"},{"clave":"C","texto":"8","tipo_error":"operacion_equivocada"},{"clave":"D","texto":"12","tipo_error":null}]',
   'D', 2, 'visual', 'Cada cuadrito vale 2 estudiantes: 6 cuadritos son 6 × 2 = 12. Si contamos solo los cuadritos olvidamos la escala del gráfico.'),
  ('DAT-05', 'datos', 'En el curso votaron: manzana 8, plátano 5, uva 11 y pera 3. ¿Cuántos votos más tuvo la uva que el plátano?',
   '[{"clave":"A","texto":"5","tipo_error":"lectura_grafico"},{"clave":"B","texto":"6","tipo_error":null},{"clave":"C","texto":"11","tipo_error":"lectura_grafico"},{"clave":"D","texto":"16","tipo_error":"operacion_equivocada"}]',
   'B', 2, 'numerica', '«Cuántos más» es una comparación: restamos 11 − 5 = 6. La uva tuvo 6 votos más que el plátano.'),
  ('DAT-06', 'datos', 'En una bolsa hay 5 bolitas azules y 1 verde. Si sacas una sin mirar, ¿qué es más probable?',
   '[{"clave":"A","texto":"Sacar una azul","tipo_error":null},{"clave":"B","texto":"Sacar la verde","tipo_error":"probabilidad_terminos"},{"clave":"C","texto":"Las dos son igual de probables","tipo_error":"probabilidad_terminos"},{"clave":"D","texto":"Sacar una roja","tipo_error":"probabilidad_terminos"}]',
   'A', 3, 'verbal', 'Hay más bolitas azules (5) que verdes (1), así que es más probable sacar una azul. Sacar una roja es imposible: no hay rojas.'),
  ('DAT-07', 'datos', 'En una tabla de conteo cada grupo de 4 rayitas cruzadas por una quinta vale 5. Los que llegan en bus tienen 2 grupos completos y 3 rayitas sueltas. ¿Cuántos son?',
   '[{"clave":"A","texto":"5","tipo_error":"conteo_tabla"},{"clave":"B","texto":"10","tipo_error":"conteo_tabla"},{"clave":"C","texto":"13","tipo_error":null},{"clave":"D","texto":"23","tipo_error":"conteo_tabla"}]',
   'C', 3, 'concreta', 'Cada grupo completo vale 5: 2 grupos son 10. Sumamos las 3 rayitas sueltas: 10 + 3 = 13.')
) AS v(codigo, eje, enunciado, opciones, correcta, dificultad, estrategia, explicacion)
JOIN eje e ON e.codigo = v.eje
ON CONFLICT (codigo) DO UPDATE SET
  eje_id = EXCLUDED.eje_id,
  enunciado = EXCLUDED.enunciado,
  opciones = EXCLUDED.opciones,
  respuesta_correcta = EXCLUDED.respuesta_correcta,
  dificultad = EXCLUDED.dificultad,
  estrategia = EXCLUDED.estrategia,
  explicacion = EXCLUDED.explicacion,
  actualizado_en = now()
WHERE NOT pregunta.revisada_pedagogicamente;
